from datetime import datetime

from app.extensions import db


class MediaFile(db.Model):
    """Private media generated by a user's detection request."""

    __tablename__ = "media_file"

    uid = db.Column(db.String(32), primary_key=True)  # UUID hex; never a user-supplied path
    owner_id = db.Column(db.Integer, db.ForeignKey("user.id"), nullable=False, index=True)
    original_name = db.Column(db.String(255), nullable=False)
    source_filename = db.Column(db.String(100), nullable=False, unique=True)
    result_filename = db.Column(db.String(100), nullable=False, unique=True)
    model_name = db.Column(db.String(40), nullable=False)
    source_extension = db.Column(db.String(10), nullable=False)
    result_extension = db.Column(db.String(10), nullable=False)
    people_count = db.Column(db.Integer, nullable=False, default=0)
    cars_count = db.Column(db.Integer, nullable=False, default=0)
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow, index=True)

    owner = db.relationship("User", backref=db.backref("media_files", lazy=True))
